import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.2cFhd8Ux.js";const g=JSON.parse('{"title":"Week 5 — Spec-Driven Development","description":"","frontmatter":{"source":"weeks/05-spec-driven-development/README.md"},"headers":[],"relativePath":"weeks/05-spec-driven-development/index.md","filePath":"weeks/05-spec-driven-development/index.md"}'),s={name:"weeks/05-spec-driven-development/index.md"};function n(i,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="week-5--spec-driven-development" tabindex="-1">Week 5 — Spec-Driven Development <a class="header-anchor" href="#week-5--spec-driven-development" aria-label="Permalink to &quot;Week 5 — Spec-Driven Development&quot;">​</a></h1><blockquote><p>When an agent can build almost anything you describe, the description is the engineering: write what &quot;done&quot; means, in checkable terms, before anyone writes code, and expect it to change.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before the Seminar</strong></td><td>Read the reading and post your reading response on Canvas · submit the week 4 defense and threat model (the Seminar opens with its quiz) · if a graduate paper is presented, post one question about it (<a href="./../../graduate/paper-presentations.html#questions-from-the-class">how</a>)</td></tr><tr><td><strong>Seminar</strong></td><td>Due-date quiz on the week 4 assignment (7 min, 🔴 AI off) · talk (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-05.html" target="_blank" rel="noreferrer">slides</a>) · debate on the reading · demo: a one-shot plan versus a plan from a spec · Lab preview</td></tr><tr><td><strong>Lab</strong></td><td><a href="./lab.html#lab--spec-a-feature-then-build-its-first-task-75-min">Spec a feature</a> in the <code>roomly</code> kit, then build its first task. <strong>Checkoff:</strong> an approved <code>SPEC.md</code> with testable criteria, and the first task merged with a test</td></tr><tr><td><strong>Due before next week&#39;s Seminar</strong></td><td>Default 11:59 pm the night before: the <a href="./lab.html#assignment--recurring-bookings-in-two-beats">assignment</a>: finish the feature; <strong>beat 2</strong> changes the spec on day 3, and you say what it broke</td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: implementing tasks (plan mode, approvals on) and critiquing your spec · 🟡 AI limited: <code>SPEC.md</code>, <code>DESIGN.md</code>, <code>TASKS.md</code> (you write them; an AI may critique, logged) · 🔴 AI off: the quiz, the reading response, and your beat 2 note</td></tr><tr><td><strong>Reading</strong></td><td>Martin Kleppmann, <a href="https://martin.kleppmann.com/2025/12/08/ai-formal-verification.html" target="_blank" rel="noreferrer">&quot;Prediction: AI will make formal verification go mainstream&quot;</a> (Dec 2025)</td></tr><tr><td><strong>Reading response</strong></td><td>150–250 words on Canvas, 🔴 AI off, before the Seminar (prompt <a href="#reading">below</a>)</td></tr><tr><td><strong>Team project</strong></td><td><strong>M0 proposal</strong> due before the week 6 Seminar: issues, <code>course/SPEC.md</code>, <code>DESIGN.md</code>, <code>TASKS.md</code> and the team setup (<a href="./../../project/milestones.html#m0-proposal">milestones</a>). The Lab rehearses it</td></tr><tr><td><strong>Graduate track</strong></td><td>No seminar paper is set for this topic. Choose your study; your own proposals go to the instructor by the end of this week (<a href="./../../graduate/empirical-study.html#your-own-proposal">empirical study</a>); the protocol is due before the week 7 Seminar</td></tr><tr><td><strong>Time</strong></td><td>Meetings 2.5 h · outside about 6 h (CS [5xxx]: about 7.5 h): reading and response 45 min, assignment about 3.5 h, team project about 1.75 h</td></tr></tbody></table><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Write acceptance criteria in <a href="./../../resources/glossary.html#ears">EARS</a> form (&quot;WHEN … THE SYSTEM SHALL …&quot;) that a test can check, edge cases included.</li><li>Keep requirements, design and tasks apart in <code>SPEC.md</code>, <code>DESIGN.md</code> and <code>TASKS.md</code>, and split a feature into agent-sized tasks with Specify · Delegate · Verify lines.</li><li>Use <a href="./../../resources/glossary.html#plan-mode">plan mode</a>: get an agent&#39;s plan, edit it, and execute it one verified step at a time.</li><li>Run a <a href="./../../resources/glossary.html#goldfish-test">Goldfish test</a> on a spec and fix what it finds in the document, not in the chat.</li><li>Absorb a mid-assignment change to the spec (a <a href="./../../resources/glossary.html#beat">beat</a>) and say exactly what it broke.</li><li>Explain what the evidence says about writing specifications and checks before code, and where it stops.</li></ol><h2 id="seminar" tabindex="-1">Seminar <a class="header-anchor" href="#seminar" aria-label="Permalink to &quot;Seminar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Block</th><th>Minutes</th><th>What happens</th></tr></thead><tbody><tr><td>Due-date quiz</td><td>7</td><td>On your week 4 defense and threat model (<a href="./../../assessment/quizzes.html">quizzes</a>), 🔴 AI off</td></tr><tr><td>Concept talk</td><td>25</td><td>Requirements → design → tasks; EARS; edge cases; plan mode; agent-sized tasks; beats (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-05.html" target="_blank" rel="noreferrer">slides</a>)</td></tr><tr><td>Debate</td><td>20</td><td>&quot;Specs are the new code&quot;, argued from the reading and the evidence (or a graduate presentation)</td></tr><tr><td>Live demo</td><td>10</td><td>An agent plans recurring bookings twice: from a one-line prompt, then from a short spec</td></tr><tr><td>Lab preview</td><td>5</td><td>The checkoff, the <code>shipped</code> tag, and why beat 2 exists</td></tr></tbody></table><p>The evidence: LLMs produced formally verified code for 82% of specifications in Dafny (up from 68% a year earlier), 44% in Verus and 27% in Lean, so the hard part becomes the specification (<a href="https://arxiv.org/abs/2509.22908" target="_blank" rel="noreferrer">Bursuc et al.</a>, preprint). Tests generated after faulty code caught 14% of its faults, against 25% when generated independently (<a href="https://arxiv.org/abs/2607.05139" target="_blank" rel="noreferrer">Konstantinou, Tambon &amp; Papadakis</a>, preprint): write the check first. Agents fail more as tasks get longer (<a href="https://arxiv.org/abs/2503.14499" target="_blank" rel="noreferrer">Kwa et al.</a>) and as context grows (<a href="https://www.trychroma.com/research/context-rot" target="_blank" rel="noreferrer">Hong et al.</a>): keep tasks small. And UT Austin&#39;s CS 378 hands out homework &quot;in beats&quot;, because the spec changes under you (<a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378</a>).</p><h2 id="lab" tabindex="-1">Lab <a class="header-anchor" href="#lab" aria-label="Permalink to &quot;Lab&quot;">​</a></h2><p>The <a href="./lab.html#lab--spec-a-feature-then-build-its-first-task-75-min">lab</a> introduces the <a href="https://github.com/Boyu-Zhang-UOI/eswa-roomly" target="_blank" rel="noreferrer"><code>roomly</code> kit</a>, a deliberately messy room-booking API you&#39;ll use in weeks 5–10 and 13; its README&#39;s <strong>Booking rules</strong> are its specification. Recurring bookings aren&#39;t implemented yet. You turn the facilities office&#39;s request into <code>SPEC.md</code>, test it on a fresh agent session, then build the first task in plan mode, test first. In the <a href="./lab.html#assignment--recurring-bookings-in-two-beats">assignment</a> you finish the feature, and on day 3 the facilities office changes its mind.</p><h2 id="reading" tabindex="-1">Reading <a class="header-anchor" href="#reading" aria-label="Permalink to &quot;Reading&quot;">​</a></h2><p><strong>Martin Kleppmann, <a href="https://martin.kleppmann.com/2025/12/08/ai-formal-verification.html" target="_blank" rel="noreferrer">&quot;Prediction: AI will make formal verification go mainstream&quot;</a></strong> (December 2025). A short essay: proof checkers are mechanical and LLMs are getting good at writing proofs, so the expensive, human part becomes stating what the program should do. Read it with the vericoding numbers in mind (<a href="./../../resources/reading-list.html#week-5--spec-driven-development">reading list</a>).</p><p><strong>Reading response prompt</strong> (150–250 words, 🔴 AI off, on Canvas): State Kleppmann&#39;s main claim and the strongest evidence for it. Then name one kind of mistake that no proof or passing test suite can catch, because it lives in the specification itself. Could your <code>SPEC.md</code> for recurring bookings contain it, and which step of this week&#39;s workflow (the Goldfish test, check first, the beat) would catch it, if any? End with one question for the Seminar.</p><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><ul><li><strong>Three documents.</strong> <code>SPEC.md</code> says <em>what</em> must be true, and what&#39;s out of scope; <code>DESIGN.md</code> says <em>how</em>, recording decisions a reviewer could have made differently; <code>TASKS.md</code> splits the work into agent-sized pieces (<a href="./../../templates/SPEC.html">templates</a>).</li><li><strong>EARS makes criteria testable</strong>, but only if the response is observable. &quot;Handles daylight saving correctly&quot; isn&#39;t a criterion; a WHEN with dates, times and the expected result is. If you can&#39;t name the test in the &quot;Verified by&quot; column, the criterion isn&#39;t done.</li><li><strong>Edge cases belong in the spec.</strong> Boundaries, the days the clocks change, partial failure, limits, and who may do what. Asked to &quot;add recurring bookings&quot;, an agent decides all of these for you, silently.</li><li><strong>Plan mode is a design review in miniature.</strong> You delete steps outside the task, put the test first, and approve one step at a time (<a href="./../../resources/agent-patterns.html#plan-first">plan first</a>). &quot;A one-shot prompt gives you the model&#39;s design, not yours&quot; (<a href="https://github.com/eecs498-aase/materials/blob/HEAD/labs/Lab03/slides.md" target="_blank" rel="noreferrer">Michigan EECS 498</a>).</li><li><strong>Agent-sized means reviewable:</strong> one task, one session, one diff a teammate reads in one sitting (<a href="./../../resources/agent-patterns.html#small-tasks">small tasks</a>). Its test is written first, from the criterion alone (<a href="./../../resources/glossary.html#check-first">check first</a>).</li><li><strong>Specs change.</strong> Record a beat in the spec&#39;s change table, keep criterion IDs stable, and follow it through design, tasks and tests. What breaks shows how well v1 was designed.</li></ul><h2 id="check-your-understanding" tabindex="-1">Check your understanding <a class="header-anchor" href="#check-your-understanding" aria-label="Permalink to &quot;Check your understanding&quot;">​</a></h2><ol><li>Rewrite &quot;every occurrence follows the Booking rules&quot; as an EARS criterion a test could check. What did you have to decide to write it?</li><li>Your agent&#39;s plan for task T1 includes &quot;refactor <code>createBooking</code> for clarity&quot;. What do you do with that step, and why?</li><li>A fresh session given only your <code>SPEC.md</code> asks &quot;what if the fourth occurrence clashes with an existing booking?&quot; Where does the answer go, and why not in the chat?</li><li>Why is a task&#39;s test written before the code, from the criterion alone? Cite the number.</li><li>Suppose the facilities office later asked for series every two weeks as well as every week. Which of your v1 tests would you expect to break, and is that a sign of a bad test or a good one?</li></ol><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><ul><li><strong>The CLI agent is down or out of allowance:</strong> use a fallback from <a href="./../../TOOLS.html#tools-by-week">Tool Handout: Tools by week</a> (week 5 row), or OpenCode with the lab machine&#39;s Ollama (<a href="./../../setup/local-models.html">local models</a>). The &quot;don&#39;t edit anything yet&quot; prompt replaces plan mode anywhere.</li><li><strong>No agent at all:</strong> a classmate who hasn&#39;t seen your work is the goldfish (they read only your <code>SPEC.md</code> and list their questions), and you write T1 yourself under the Safe Loop. Say so in <code>AI_LOG.md</code>.</li><li><strong>No network:</strong> <code>roomly</code> needs no packages. Codespace trouble: <a href="./../../resources/troubleshooting.html#my-codespace-wont-start-or-im-out-of-hours">troubleshooting</a>.</li></ul><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Bursuc et al., <a href="https://arxiv.org/abs/2509.22908" target="_blank" rel="noreferrer">&quot;A benchmark for vericoding&quot;</a>, and Konstantinou, Tambon &amp; Papadakis, <a href="https://arxiv.org/abs/2607.05139" target="_blank" rel="noreferrer">&quot;On the risk of coding before testing&quot;</a>.</li><li>Michigan EECS 498&#39;s <a href="https://github.com/eecs498-aase/materials/blob/HEAD/egm/README.md" target="_blank" rel="noreferrer">Elephant-Goldfish Model</a>: a design document and a review ledger, required before implementation.</li><li>Previous week: <a href="./../04-securing-agents/">Securing Agents</a>. Next week: <a href="./../06-tests-as-oracles/">Tests as Oracles</a>, where <code>roomly</code>&#39;s Booking rules become the oracle for property-based tests.</li></ul>',23)])])}const m=t(s,[["render",n]]);export{g as __pageData,m as default};
